<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{TahunAnggaran,Pendapatan,Belanja,Pembiayaan,RealisasiPendapatan,RealisasiBelanja,RealisasiPembiayaan}; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class RealisasiController extends Controller { public function index():View{return view('admin.realisasi.index',['income'=>RealisasiPendapatan::with('pendapatan')->latest('tanggal')->get(),'expense'=>RealisasiBelanja::with('belanja')->latest('tanggal')->get(),'financing'=>RealisasiPembiayaan::with('pembiayaan')->latest('tanggal')->get()]);} public function create():View{return view('admin.realisasi.form',$this->data());} public function store(Request $r):RedirectResponse{$d=$this->valid($r);$this->model($d['jenis'])::create($this->payload($d));return to_route('admin.realisasi.index')->with('success','Realisasi ditambahkan.');} public function destroy(string $jenis,int $id):RedirectResponse{$this->model($jenis)::findOrFail($id)->delete();return back()->with('success','Realisasi dihapus.');} public function publication(string $jenis,int $id):RedirectResponse{$m=$this->model($jenis)::findOrFail($id);$m->update(['status_publikasi'=>$m->status_publikasi==='dipublikasikan'?'draft':'dipublikasikan']);return back()->with('success','Status publikasi diperbarui.');} private function data():array{return ['years'=>TahunAnggaran::orderByDesc('tahun')->get(),'pendapatan'=>Pendapatan::orderBy('uraian')->get(),'belanja'=>Belanja::orderBy('uraian')->get(),'pembiayaan'=>Pembiayaan::orderBy('uraian')->get()];} private function valid(Request $r):array{return $r->validate(['jenis'=>'required|in:pendapatan,belanja,pembiayaan','tahun_anggaran_id'=>'required|exists:tahun_anggaran,id','item_id'=>'required|integer','bulan'=>'required|integer|between:1,12','tanggal'=>'required|date','nilai'=>'required|numeric|min:0','keterangan'=>'nullable|string','status_publikasi'=>'required|in:draft,dipublikasikan']);} private function payload(array $d):array{$type=$d['jenis'];unset($d['jenis']);$d[$type.'_id']=$d['item_id'];unset($d['item_id']);return $d;} private function model(string $type):string{return match($type){'pendapatan'=>RealisasiPendapatan::class,'belanja'=>RealisasiBelanja::class,'pembiayaan'=>RealisasiPembiayaan::class,default=>abort(404)};}}
